foreach ($rel in $map.Keys) {
    $target = if ($rel -eq "") { $root } else { Join-Path $root $rel }
    if (Test-Path $target) {
        try {
            $acl = Get-Acl -LiteralPath $target
            $sddlText = $map[$rel]
            $acl.SetSecurityDescriptorSddlForm($sddlText, [System.Security.AccessControl.AccessControlSections]::Access)
            Set-Acl -LiteralPath $target -AclObject $acl
            Write-Host "SUCCESS applying DACL to: '$rel'"
        } catch {
            Write-Host "Error applying DACL to '$rel': $_"
        }
    }
}
